pub fn upgrade(&self) -> Option<Rc<'a, T>> {
    if self.strong_count() > 0 {
        // Safely upgrade to a strong reference
        let strong_count = self.strong().get();
        let new_rc = Rc {
            inner: self.inner.clone(), // Create a new Rc with the same inner
        };
        new_rc.strong().set(strong_count + 1); // Increment the strong count
        Some(new_rc)
    } else {
        None
    }
}
